create table if not exists public.fleet_metric_definitions (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, created_by uuid not null references auth.users(id), metric_key text not null, feature_code text not null, name text not null, description text, unit text, source_dataset text not null, source_metric text not null, aggregation text not null default 'avg', direction text not null default 'higher_is_better', scoring_method text not null default 'threshold', goal numeric, threshold numeric, max_score numeric not null default 100, scoring_config jsonb not null default '{}'::jsonb, period text not null default 'week', active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint fleet_metric_definitions_aggregation_ck check (aggregation in ('sum','avg','min','max','count','rate','latest')), constraint fleet_metric_definitions_direction_ck check (direction in ('higher_is_better','lower_is_better')), constraint fleet_metric_definitions_scoring_method_ck check (scoring_method in ('threshold','linear','binary','banded')), constraint fleet_metric_definitions_period_ck check (period in ('day','week','month','quarter','custom')), constraint fleet_metric_definitions_max_score_ck check (max_score >= 0), constraint fleet_metric_definitions_scoring_config_object_ck check (jsonb_typeof(scoring_config) = 'object'), constraint fleet_metric_definitions_name_ck check (length(trim(name)) > 0));
create unique index if not exists fleet_metric_definitions_business_key_idx on public.fleet_metric_definitions(business_id, metric_key);
create index if not exists fleet_metric_definitions_business_idx on public.fleet_metric_definitions(business_id, active, updated_at desc);
create table if not exists public.fleet_metric_assignments (id uuid primary key default gen_random_uuid(), metric_definition_id uuid not null references public.fleet_metric_definitions(id) on delete cascade, business_id uuid not null references public.businesses(id) on delete cascade, target_type text not null, target_id uuid, assigned_by uuid not null references auth.users(id), active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint fleet_metric_assignments_target_type_ck check (target_type in ('fleet','driver','vehicle','route')), constraint fleet_metric_assignments_target_ck check ((target_type='fleet' and target_id is null) or (target_type<>'fleet' and target_id is not null)));
create unique index if not exists fleet_metric_assignments_unique_active_idx on public.fleet_metric_assignments(metric_definition_id,target_type,target_id) where active;
create index if not exists fleet_metric_assignments_business_target_idx on public.fleet_metric_assignments(business_id,target_type,target_id,active);
alter table public.fleet_metric_definitions enable row level security;
alter table public.fleet_metric_assignments enable row level security;
revoke all on public.fleet_metric_definitions from anon,authenticated;
revoke all on public.fleet_metric_assignments from anon,authenticated;
create or replace function public.fleet_metric_controller_authorized(p_business_id uuid) returns boolean language sql stable security definer set search_path=public,pg_catalog as $$ select exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=(select auth.uid()) and lower(bm.role::text) in ('owner','admin','manager')) and public.has_fleet_access(p_business_id); $$;
revoke all on function public.fleet_metric_controller_authorized(uuid) from public,anon;
grant execute on function public.fleet_metric_controller_authorized(uuid) to authenticated;
create or replace function public.fleet_metric_source_allowed(p_dataset text,p_metric text) returns boolean language sql immutable as $$ select (trim(p_dataset),trim(p_metric)) in (('fleet_metric_snapshots','vehicles_active'),('fleet_metric_snapshots','routes_completed'),('fleet_metric_snapshots','stops_completed'),('fleet_metric_snapshots','restroom_coverage_score'),('fleet_metric_snapshots','average_stop_distance_miles'),('fleet_metric_snapshots','estimated_time_saved_minutes'),('fleet_driver_scorecards','safety_score'),('fleet_driver_scorecards','efficiency_score'),('fleet_driver_scorecards','route_completion_score'),('fleet_driver_scorecards','idle_minutes'),('fleet_driver_scorecards','harsh_braking_count'),('fleet_driver_scorecards','harsh_acceleration_count'),('fleet_driver_scorecards','speeding_events'),('fleet_driver_scorecards','collision_events'),('fleet_driver_scorecards','seatbelt_events'),('fleet_vehicle_daily_metrics','miles'),('fleet_vehicle_daily_metrics','engine_hours'),('fleet_vehicle_daily_metrics','trips'),('fleet_vehicle_daily_metrics','fuel_units'),('fleet_vehicle_daily_metrics','energy_kwh'),('fleet_vehicle_daily_metrics','idle_minutes'),('fleet_vehicle_daily_metrics','utilization_pct'),('fleet_vehicle_daily_metrics','fault_events')); $$;
revoke all on function public.fleet_metric_source_allowed(text,text) from public,anon;
grant execute on function public.fleet_metric_source_allowed(text,text) to authenticated;
create or replace function public.create_fleet_metric_definition(p_business_id uuid,p_metric_key text,p_feature_code text,p_name text,p_description text default null,p_unit text default null,p_source_dataset text default null,p_source_metric text default null,p_aggregation text default 'avg',p_direction text default 'higher_is_better',p_scoring_method text default 'threshold',p_goal numeric default null,p_threshold numeric default null,p_max_score numeric default 100,p_scoring_config jsonb default '{}'::jsonb,p_period text default 'week') returns public.fleet_metric_definitions language plpgsql security definer set search_path=public,pg_catalog as $$ declare v public.fleet_metric_definitions; f public.feature_catalog; begin if (select auth.uid()) is null then raise exception 'Authentication required'; end if; if not public.fleet_metric_controller_authorized(p_business_id) then raise exception 'Fleet controller authorization required'; end if; select * into f from public.feature_catalog where feature_code=trim(p_feature_code) and enabled=true; if not found then raise exception 'Fleet feature is unavailable: %',p_feature_code; end if; if lower(coalesce(f.category,''))<>'fleet' and trim(p_feature_code) not like 'fleet_%' then raise exception 'Feature is not a Fleet capability: %',p_feature_code; end if; if not public.fleet_metric_source_allowed(p_source_dataset,p_source_metric) then raise exception 'Unsupported Fleet metric source: %.%',p_source_dataset,p_source_metric; end if; insert into public.fleet_metric_definitions(business_id,created_by,metric_key,feature_code,name,description,unit,source_dataset,source_metric,aggregation,direction,scoring_method,goal,threshold,max_score,scoring_config,period) values(p_business_id,(select auth.uid()),trim(p_metric_key),trim(p_feature_code),trim(p_name),p_description,p_unit,trim(p_source_dataset),trim(p_source_metric),lower(trim(p_aggregation)),lower(trim(p_direction)),lower(trim(p_scoring_method)),p_goal,p_threshold,p_max_score,coalesce(p_scoring_config,'{}'::jsonb),lower(trim(p_period))) returning * into v; return v; end; $$;
create or replace function public.update_fleet_metric_definition(p_metric_definition_id uuid,p_name text default null,p_description text default null,p_goal numeric default null,p_threshold numeric default null,p_max_score numeric default null,p_scoring_method text default null,p_scoring_config jsonb default null,p_period text default null,p_active boolean default null) returns public.fleet_metric_definitions language plpgsql security definer set search_path=public,pg_catalog as $$ declare v public.fleet_metric_definitions; b uuid; begin select business_id into b from public.fleet_metric_definitions where id=p_metric_definition_id; if b is null then raise exception 'Fleet metric definition not found'; end if; if not public.fleet_metric_controller_authorized(b) then raise exception 'Fleet controller authorization required'; end if; update public.fleet_metric_definitions set name=coalesce(nullif(trim(p_name),''),name),description=coalesce(p_description,description),goal=coalesce(p_goal,goal),threshold=coalesce(p_threshold,threshold),max_score=coalesce(p_max_score,max_score),scoring_method=coalesce(lower(trim(p_scoring_method)),scoring_method),scoring_config=coalesce(p_scoring_config,scoring_config),period=coalesce(lower(trim(p_period)),period),active=coalesce(p_active,active),updated_at=now() where id=p_metric_definition_id returning * into v; return v; end; $$;
create or replace function public.assign_fleet_metric(p_metric_definition_id uuid,p_target_type text,p_target_id uuid default null) returns public.fleet_metric_assignments language plpgsql security definer set search_path=public,pg_catalog as $$ declare d public.fleet_metric_definitions; v public.fleet_metric_assignments; t text:=lower(trim(p_target_type)); begin select * into d from public.fleet_metric_definitions where id=p_metric_definition_id; if not found then raise exception 'Fleet metric definition not found'; end if; if not public.fleet_metric_controller_authorized(d.business_id) then raise exception 'Fleet controller authorization required'; end if; if t not in ('fleet','driver','vehicle','route') then raise exception 'Invalid Fleet metric target type'; end if; if (t='fleet')<>(p_target_id is null) then raise exception 'Target id mismatch'; end if; if t='driver' and not exists(select 1 from public.fleet_drivers x where x.id=p_target_id and x.business_id=d.business_id) then raise exception 'Driver target is outside this Fleet'; end if; if t='vehicle' and not exists(select 1 from public.fleet_vehicles x where x.id=p_target_id and x.business_id=d.business_id) then raise exception 'Vehicle target is outside this Fleet'; end if; if t='route' and not exists(select 1 from public.fleet_routes x where x.id=p_target_id and x.business_id=d.business_id) then raise exception 'Route target is outside this Fleet'; end if; insert into public.fleet_metric_assignments(metric_definition_id,business_id,target_type,target_id,assigned_by) values(p_metric_definition_id,d.business_id,t,p_target_id,(select auth.uid())) on conflict (metric_definition_id,target_type,target_id) where active do update set assigned_by=excluded.assigned_by,updated_at=now() returning * into v; return v; end; $$;
create or replace function public.get_fleet_metric_configuration(p_business_id uuid) returns jsonb language sql stable security definer set search_path=public,pg_catalog as $$ select jsonb_build_object('business_id',p_business_id,'definitions',coalesce((select jsonb_agg(to_jsonb(d) order by d.created_at) from public.fleet_metric_definitions d where d.business_id=p_business_id),'[]'::jsonb),'assignments',coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at) from public.fleet_metric_assignments a where a.business_id=p_business_id and a.active),'[]'::jsonb)) where public.has_fleet_access(p_business_id); $$;
create or replace function public.get_fleet_metric_values(p_business_id uuid,p_as_of date default current_date) returns jsonb language plpgsql stable security definer set search_path=public,pg_catalog as $$ declare d record; result jsonb:='[]'::jsonb; start_date date; v numeric; score numeric; begin if not public.has_fleet_access(p_business_id) then raise exception 'Fleet access required'; end if; for d in select * from public.fleet_metric_definitions where business_id=p_business_id and active loop start_date:=case d.period when 'day' then p_as_of when 'week' then p_as_of-6 when 'month' then p_as_of-29 when 'quarter' then p_as_of-89 else p_as_of-6 end; v:=null; if d.source_dataset='fleet_metric_snapshots' then execute format('select %s(%I) from public.fleet_metric_snapshots where business_id=$1 and snapshot_date between $2 and $3',d.aggregation,d.source_metric) into v using p_business_id,start_date,p_as_of; elsif d.source_dataset='fleet_driver_scorecards' then execute format('select %s(%I) from public.fleet_driver_scorecards where business_id=$1 and score_date between $2 and $3',d.aggregation,d.source_metric) into v using p_business_id,start_date,p_as_of; elsif d.source_dataset='fleet_vehicle_daily_metrics' then execute format('select %s(%I) from public.fleet_vehicle_daily_metrics where business_id=$1 and metric_date between $2 and $3',d.aggregation,d.source_metric) into v using p_business_id,start_date,p_as_of; end if; if v is not null then score:=case when d.scoring_method='binary' and ((d.direction='higher_is_better' and v>=coalesce(d.threshold,d.goal)) or (d.direction='lower_is_better' and v<=coalesce(d.threshold,d.goal))) then d.max_score when d.scoring_method='threshold' and ((d.direction='higher_is_better' and v>=coalesce(d.threshold,d.goal)) or (d.direction='lower_is_better' and v<=coalesce(d.threshold,d.goal))) then d.max_score when d.scoring_method='linear' and d.goal is not null then greatest(0,least(d.max_score,case when d.direction='higher_is_better' then d.max_score*v/d.goal else d.max_score*d.goal/nullif(v,0) end)) else null end; end if; result:=result||jsonb_build_array(jsonb_build_object('definition_id',d.id,'metric_key',d.metric_key,'name',d.name,'source_dataset',d.source_dataset,'source_metric',d.source_metric,'period',d.period,'value',v,'score',score,'goal',d.goal,'threshold',d.threshold,'direction',d.direction,'max_score',d.max_score)); end loop; return result; end; $$;
revoke all on function public.create_fleet_metric_definition(uuid,text,text,text,text,text,text,text,text,text,text,numeric,numeric,numeric,jsonb,text) from public,anon;
revoke all on function public.update_fleet_metric_definition(uuid,text,text,numeric,numeric,numeric,text,jsonb,text,boolean) from public,anon;
revoke all on function public.assign_fleet_metric(uuid,text,uuid) from public,anon;
revoke all on function public.get_fleet_metric_configuration(uuid) from public,anon;
revoke all on function public.get_fleet_metric_values(uuid,date) from public,anon;
grant execute on function public.create_fleet_metric_definition(uuid,text,text,text,text,text,text,text,text,text,text,numeric,numeric,numeric,jsonb,text) to authenticated;
grant execute on function public.update_fleet_metric_definition(uuid,text,text,numeric,numeric,numeric,text,jsonb,text,boolean) to authenticated;
grant execute on function public.assign_fleet_metric(uuid,text,uuid) to authenticated;
grant execute on function public.get_fleet_metric_configuration(uuid) to authenticated;
grant execute on function public.get_fleet_metric_values(uuid,date) to authenticated;
comment on table public.fleet_metric_definitions is 'Controller-authored Fleet configuration over allowlisted authoritative Fleet measurements; not a metrics engine.';
comment on table public.fleet_metric_assignments is 'Fleet metric scope assignments for fleet, driver, vehicle, or route.';
